SELECT brand, DATE_TRUNC('QUARTER', launch_date) AS quarter_start, COUNT(CASE WHEN category = 'Fashion' THEN 1 END) AS fashion_count, APPROX_PERCENTILE(stock_qty, ARRAY(0.25, 0.5, 0.75)) AS stock_qty_quartiles, ROUND(SUM(stock_qty) / NULLIF(COUNT(CASE WHEN category = 'Home' THEN 1 END), 0), 2) AS stock_qty_per_home, GROUPING(brand) AS grouping_level FROM products GROUP BY CUBE (brand, DATE_TRUNC('QUARTER', launch_date))
